frameworks.dockerfile_template:
FROM frappe/frappe-worker:latest
USER root
{{if .IsBench}}
COPY sites /home/frappe/frappe-bench/sites
{{range .CustomApps}}
COPY apps/{{.}} /home/frappe/frappe-bench/apps/{{.}}
{{end}}
{{else}}
RUN mkdir -p /home/frappe/frappe-bench/apps/{{index .CustomApps 0}}
COPY . /home/frappe/frappe-bench/apps/{{index .CustomApps 0}}
{{end}}
RUN cd /home/frappe/frappe-bench && \
{{range .CustomApps}}
  ./env/bin/pip install -q -U -e apps/{{.}} && \
{{end}}
  echo "Custom apps installed"
RUN echo 'import os
from frappe.app import application as frappe_app

def application(environ, start_response):
    if "HTTP_X_FRAPPE_SITE_NAME" not in environ:
        try:
            with open("/home/frappe/frappe-bench/sites/currentsite.txt", "r") as f:
                environ["HTTP_X_FRAPPE_SITE_NAME"] = f.read().strip()
        except Exception:
            pass
    return frappe_app(environ, start_response)' > /home/frappe/frappe-bench/sites/serve.py
RUN python3 -c "import json, os; p='/home/frappe/frappe-bench/sites/common_site_config.json'; c=json.load(open(p)) if os.path.exists(p) else {}; c.update({'db_host': 'db', 'redis_cache': 'redis://redis:6379', 'redis_queue': 'redis://redis:6379', 'redis_socketio': 'redis://redis:6379'}); json.dump(c, open(p, 'w'))"
RUN echo 'import json, os, time
import pymysql
import pymysql.err
site = open("/home/frappe/frappe-bench/sites/currentsite.txt").read().strip()
site_conf = json.load(open(f"/home/frappe/frappe-bench/sites/{site}/site_config.json"))
db_user = site_conf.get("db_name", site)
db_pass = site_conf.get("db_password", site)
conn = None
for i in range(30):
    try:
        conn = pymysql.connect(host="db", user=db_user, password=db_pass, database=db_user)
        break
    except Exception:
        time.sleep(1)
try:
    if conn:
        conn.cursor().execute("SELECT 1 FROM tabDocType LIMIT 1")
except pymysql.err.ProgrammingError:
    print("Database is empty. Initializing...")
    os.system(f"bench --site {site} reinstall --db-root-password "{db_pass}" --admin-password admin --yes")
except Exception as e:
    pass
os.execv("/home/frappe/frappe-bench/env/bin/gunicorn", ["gunicorn", "--bind=0.0.0.0:8000", "--threads=4", "--workers=2", "--worker-class=gthread", "--timeout=120", "serve:application"])
' > /home/frappe/frappe-bench/sites/start.py
RUN chown -R frappe:frappe /home/frappe/frappe-bench/apps /home/frappe/frappe-bench/sites
USER frappe
CMD ["/home/frappe/frappe-bench/env/bin/python", "/home/frappe/frappe-bench/sites/start.py"]
